def solve_n_queens(n):
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or \
               board[i] - i == col - row or \
               board[i] + i == col + row:
                return False
        return True

    def backtrack(row, board):
        if row == n:
            return board
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                result = backtrack(row + 1, board)
                if result:
                    return result
        return None

    return backtrack(0, [0] * n)

solution = solve_n_queens(11)
print(solution)
